// ============================================================
// 이 파일은 원본 moves.ts의 Effect 텍스트를 파싱해서
// effects 필드(구조화된 부가효과)를 추가한 버전입니다.
//
// self/target 판정은 마인라인 포켓몬 기준 문법 규칙으로 확정했습니다
// (포켓몬 챔피언스는 마인라인과 기술 효과 차이가 없음이 확인됨).
// ============================================================

export type StatKey = 'A' | 'B' | 'C' | 'D' | 'S' | 'ACC' | 'EVA' | 'CRIT';
export type EffectTarget = 'self' | 'opponent';

export type FieldScope = 'self' | 'opponent' | 'global';

export type MoveEffect =
  | { type: 'rank'; target: EffectTarget; stat: StatKey; amount: number; chance?: number }
  | { type: 'status'; target: EffectTarget; status: string; chance?: number }
  | { type: 'multiHit'; min: number; max: number }
  | { type: 'recoil'; ratio: number }
  | { type: 'heal'; ratio: number }
  | { type: 'drain'; ratio: number }
  // key: 이 필드효과를 설치하는 기술 자신의 이름 (예: '독압정', '리플렉터', '쾌청').
  // scope: 'self'=사용자측 필드, 'opponent'=상대측 필드, 'global'=필드 전체(날씨/필드/룸 등).
  // maxStack: 엔트리 해저드처럼 여러 번 설치해 단계가 올라가는 기술만 존재 (예: 독압정=2, 압정뿌리기=3).
  | { type: 'field'; scope: FieldScope; key: string; maxStack?: number }
  | { type: 'special'; raw: string }
  | { type: 'unmatched'; raw: string };

